css:
.relative {
  position: relative;
}
.flex {
  display: flex;
}
.-translate-y-5 {
  --tw-translate-y: -1.25rem;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.flex-col-reverse {
  flex-direction: column-reverse;
}
.border {
  border-width: 1px;
}
.border-black {
  --tw-border-opacity: 1;
  border-color: rgb(0 0 0 / var(--tw-border-opacity));
}
.py-1 {
  padding-top: 0.25rem;
  padding-bottom: 0.25rem;
}
.pl-2 {
  padding-left: 0.5rem;
}
.opacity-0 {
  opacity: 0;
}
.outline-none {
  outline: 2px solid transparent;
  outline-offset: 2px;
}
.duration-500 {
  transition-duration: 500ms;
}
.placeholder\:absolute::placeholder {
  position: absolute;
}
.placeholder\:duration-500::placeholder {
  transition-duration: 500ms;
}
.focus\:rounded-md:focus {
  border-radius: 0.375rem;
}
.focus\:border-dashed:focus {
  border-style: dashed;
}
.focus\:placeholder\:pt-10:focus::placeholder {
  padding-top: 2.5rem;
}
.peer:focus ~ .peer-focus\:translate-y-0 {
  --tw-translate-y: 0px;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.peer:focus ~ .peer-focus\:opacity-100 {
  opacity: 1;
}
